import{_ as e,c as l,o as i,b0 as t}from"./chunks/framework.BWMBvyU7.js";const n="/programming-docs/assets/image-20260325154437752.CKcHYLmn.png",m=JSON.parse('{"title":"LV205-从elf文件到linux进程","description":null,"frontmatter":{"title":"LV205-从elf文件到linux进程","date":"2026-03-12T16:22:49.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/compile/126d38b59fc939c56bbd1fcb","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-12T16:22:49.924Z","fulluuid":"56bbd1fcbaa8465eabfead9d1a45c663","useduuid":"56bbd1fcb"}},"headers":[],"relativePath":"sdoc/Language/c/compile/126d38b59fc939c56bbd1fcb.md","filePath":"sdoc/01-编程语言/01-C语言/20-编译基础/LV205-从elf文件到linux进程.md","lastUpdated":1774449272000}'),o={name:"sdoc/Language/c/compile/126d38b59fc939c56bbd1fcb.md"};function r(c,a,u,d,s,p){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="lv205-从elf文件到linux进程" tabindex="-1">LV205-从elf文件到linux进程 <a class="header-anchor" href="#lv205-从elf文件到linux进程" aria-label="Permalink to &quot;LV205-从elf文件到linux进程&quot;">​</a></h1><h2 id="一、elf-文件" tabindex="-1">一、ELF 文件 <a class="header-anchor" href="#一、elf-文件" aria-label="Permalink to &quot;一、ELF 文件&quot;">​</a></h2><h3 id="_1-是什么" tabindex="-1">1. 是什么？ <a class="header-anchor" href="#_1-是什么" aria-label="Permalink to &quot;1. 是什么？&quot;">​</a></h3><p>ELF（Executable and Linkable Format）文件是一种目标文件格式，用于二进制文件、可执行文件、目标代码、共享库和核心转储格式文件。它主要用于 Linux 平台，用于存储和传输可执行文件和库。</p><p>常见的文件类型‌：</p><ul><li>‌可执行文件‌：包含可执行的机器代码，可直接运行。</li><li>‌可重定位文件‌（.o 文件）：机器代码和数据地址相对，需重定位才能运行，通常用于编译过程。</li><li>‌共享对象文件（.so 文件）‌：动态链接库，包含可共享代码和数据，可在运行时被多个进程共享。</li><li>‌核心转储文件‌（core 文件）：程序崩溃或异常终止时生成，包含内存状态和寄存器信息，用于调试。</li></ul><h3 id="_2-文件格式" tabindex="-1">2. 文件格式 <a class="header-anchor" href="#_2-文件格式" aria-label="Permalink to &quot;2. 文件格式&quot;">​</a></h3><p>这里就不详细展开了，有一个中文版本的 ELF 格式文档，里面说的非常详细，可以参考：<a href="https://max.book118.com/html/2018/0523/168061908.shtm" target="_blank" rel="noreferrer">ELF 手册-中文版.pdf</a>。</p><h2 id="二、从-efl-文件到-linux-进程" tabindex="-1">二、从 EFL 文件到 linux 进程 <a class="header-anchor" href="#二、从-efl-文件到-linux-进程" aria-label="Permalink to &quot;二、从 EFL 文件到 linux 进程&quot;">​</a></h2><p>进入正题，ELF 文件是如何转变成 Linux 进程的？首先我们要知道 Linux 创建一个新的进程需要经过两个步骤：</p><ul><li>（1）父进程通过克隆方式创建子进程。</li><li>（2）子进程加载 ELF 文件生成新的进程地址空间。</li></ul><p>对于用户程序来说，实现以上两个步骤需要调用 fork 和 execve 两个系统调用。</p><p>Linux 子进程的创建必须由父进程完成，因为这样的一个约束，Linux 进程之间形成了类似于家族关系的进程关系，而所有进程的共同祖先就是 1 号进程（init）。</p><p>子进程创建时需要继承父进程的关键信息才能正常工作，从父进程继承而来的信息只能保证子进程按照父进程的方式去工作。当子进程有特定的任务需要执行，此时从父进程继承的信息就没有意义了。子进程如果需要执行特定的任务，需要加载ELF文件，替换掉子进程从父进程继承的旧信息，生成新的进程信息，这样子进程就能独立工作了。</p><p><img src="'+n+'" alt="image-20260325154437752"></p><blockquote><p>参考资料：</p><p><a href="https://mp.weixin.qq.com/s?__biz=MzkyNDIyNzU4Mg==&amp;mid=2247486346&amp;idx=1&amp;sn=ffd28a5045068754285b41a3ab42b90a&amp;scene=21&amp;poc_token=HCxlsmmj43zaij6YCR5-aVMzntqvGMF8gZPqHOxQ" target="_blank" rel="noreferrer">从 ELF 文件到 Linux 进程</a></p></blockquote>',16)])])}const b=e(o,[["render",r]]);export{m as __pageData,b as default};
